mapper.insert:
MERGE INTO CHB_LOAN_DETAIL_INFO L USING (
select #{item.assetUuid, jdbcType=CHAR} ASSET_UUID, #{item.assetCode ,jdbcType=VARCHAR } ASSET_CODE, #{item.assetsInvest ,jdbcType=VARCHAR } ASSETS_INVEST, #{item.eachProportion ,jdbcType=VARCHAR } EACH_PROPORTION, #{item.loansType ,jdbcType=VARCHAR } LOANS_TYPE, #{item.origCcy ,jdbcType=CHAR } ORIG_CCY, #{item.origContractAmount ,jdbcType=DECIMAL } ORIG_CONTRACT_AMOUNT, #{item.origContractAmountCny ,jdbcType=DECIMAL } ORIG_CONTRACT_AMOUNT_CNY, #{item.borrowerType ,jdbcType=CHAR } BORROWER_TYPE, #{item.borrowerId ,jdbcType=VARCHAR } BORROWER_ID, #{item.industryInfo ,jdbcType=CHAR } INDUSTRY_INFO, #{item.borrowerNationality ,jdbcType=VARCHAR } BORROWER_NATIONALITY, #{item.borrowerProvince ,jdbcType=VARCHAR } BORROWER_PROVINCE, #{item.borrowerCity ,jdbcType=VARCHAR } BORROWER_CITY, #{item.borrowerCounty ,jdbcType=VARCHAR } BORROWER_COUNTY, #{item.loanTransferorId ,jdbcType=VARCHAR } LOAN_TRANSFEROR_ID, #{item.loanTransferorName ,jdbcType=VARCHAR } LOAN_TRANSFEROR_NAME, #{item.loanContractOrgId ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_ID, #{item.loanContractOrgName ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_NAME, #{item.loanContractOrgProvince ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_PROVINCE, #{item.loanContractOrgCity ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_CITY, #{item.loanContractOrgCounty ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_COUNTY, #{item.enterpriseInvestorTypeFirst ,jdbcType=CHAR } ENTERPRISE_INVESTOR_TYPE_FIRST, #{item.enterpriseInvestorTypeSec ,jdbcType=CHAR } ENTERPRISE_INVESTOR_TYPE_SEC, #{item.enterpriseInvestorTypeThird ,jdbcType=CHAR } ENTERPRISE_INVESTOR_TYPE_THIRD, #{item.enterpriseScale ,jdbcType=CHAR } ENTERPRISE_SCALE, #{item.loanBasisId ,jdbcType=VARCHAR } LOAN_BASIS_ID, #{item.loanPrdType ,jdbcType=CHAR } LOAN_PRD_TYPE, #{item.loanActualInvest ,jdbcType=VARCHAR } LOAN_ACTUAL_INVEST, #{item.loanVdate ,jdbcType=DATE } LOAN_VDATE, #{item.loanMdate ,jdbcType=DATE } LOAN_MDATE, #{item.loanExtensionDueDate ,jdbcType=DATE } LOAN_EXTENSION_DUE_DATE, #{item.rateFixed ,jdbcType=VARCHAR } RATE_FIXED, #{item.rateLevel ,jdbcType=DECIMAL } RATE_LEVEL, #{item.loanGuaranteeMode ,jdbcType=CHAR } LOAN_GUARANTEE_MODE, #{item.loanQuality ,jdbcType=CHAR } LOAN_QUALITY, #{item.loanState ,jdbcType=CHAR } LOAN_STATE, #{item.loanTransferorRate ,jdbcType=DECIMAL } LOAN_TRANSFEROR_RATE, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.orgCode ,jdbcType=VARCHAR } ORG_CODE, #{item.deptCode ,jdbcType=VARCHAR } DEPT_CODE, #{item.status ,jdbcType=VARCHAR } STATUS, #{item.dataSource ,jdbcType=VARCHAR } DATA_SOURCE from dual
) TEMP ON (L.ASSET_CODE = TEMP.ASSET_CODE) WHEN MATCHED THEN UPDATE SET L.ASSET_UUID = TEMP.ASSET_UUID, L.ASSETS_INVEST = TEMP.ASSETS_INVEST, L.EACH_PROPORTION = TEMP.EACH_PROPORTION, L.LOANS_TYPE = TEMP.LOANS_TYPE, L.ORIG_CCY = TEMP.ORIG_CCY, L.ORIG_CONTRACT_AMOUNT = TEMP.ORIG_CONTRACT_AMOUNT, L.ORIG_CONTRACT_AMOUNT_CNY = TEMP.ORIG_CONTRACT_AMOUNT_CNY, L.BORROWER_TYPE = TEMP.BORROWER_TYPE, L.BORROWER_ID = TEMP.BORROWER_ID, L.INDUSTRY_INFO = TEMP.INDUSTRY_INFO, L.BORROWER_NATIONALITY = TEMP.BORROWER_NATIONALITY, L.BORROWER_PROVINCE = TEMP.BORROWER_PROVINCE, L.BORROWER_CITY = TEMP.BORROWER_CITY, L.BORROWER_COUNTY = TEMP.BORROWER_COUNTY, L.LOAN_TRANSFEROR_ID = TEMP.LOAN_TRANSFEROR_ID, L.LOAN_TRANSFEROR_NAME = TEMP.LOAN_TRANSFEROR_NAME, L.LOAN_CONTRACT_ORG_ID = TEMP.LOAN_CONTRACT_ORG_ID, L.LOAN_CONTRACT_ORG_NAME = TEMP.LOAN_CONTRACT_ORG_NAME, L.LOAN_CONTRACT_ORG_PROVINCE = TEMP.LOAN_CONTRACT_ORG_PROVINCE, L.LOAN_CONTRACT_ORG_CITY = TEMP.LOAN_CONTRACT_ORG_CITY, L.LOAN_CONTRACT_ORG_COUNTY = TEMP.LOAN_CONTRACT_ORG_COUNTY, L.ENTERPRISE_INVESTOR_TYPE_FIRST = TEMP.ENTERPRISE_INVESTOR_TYPE_FIRST, L.ENTERPRISE_INVESTOR_TYPE_SEC = TEMP.ENTERPRISE_INVESTOR_TYPE_SEC, L.ENTERPRISE_INVESTOR_TYPE_THIRD = TEMP.ENTERPRISE_INVESTOR_TYPE_SEC, L.ENTERPRISE_SCALE = TEMP.ENTERPRISE_SCALE, L.LOAN_BASIS_ID = TEMP.LOAN_BASIS_ID, L.LOAN_PRD_TYPE = TEMP.LOAN_PRD_TYPE, L.LOAN_ACTUAL_INVEST = TEMP.LOAN_ACTUAL_INVEST, L.LOAN_VDATE = TEMP.LOAN_VDATE, L.LOAN_MDATE = TEMP.LOAN_MDATE, L.LOAN_EXTENSION_DUE_DATE = TEMP.LOAN_EXTENSION_DUE_DATE, L.RATE_FIXED = TEMP.RATE_FIXED, L.RATE_LEVEL = TEMP.RATE_LEVEL, L.LOAN_GUARANTEE_MODE = TEMP.LOAN_GUARANTEE_MODE , L.LOAN_QUALITY = TEMP.LOAN_QUALITY, L.LOAN_STATE = TEMP.LOAN_STATE, L.LOAN_TRANSFEROR_RATE = TEMP.LOAN_TRANSFEROR_RATE, L.CREATE_USER = TEMP.CREATE_USER, L.CREATE_TIME = TEMP.CREATE_TIME, L.UPDATE_USER = TEMP.UPDATE_USER, L.UPDATE_TIME = TEMP.UPDATE_TIME, L.CREATE_DEPT = TEMP.CREATE_DEPT, L.ORG_CODE = TEMP.ORG_CODE, L.DEPT_CODE = TEMP.DEPT_CODE, L.STATUS = TEMP.STATUS, L.DATA_SOURCE = TEMP.DATA_SOURCE WHEN NOT MATCHED THEN INSERT ( ASSET_UUID, ASSET_CODE, ASSETS_INVEST, EACH_PROPORTION, LOANS_TYPE, ORIG_CCY, ORIG_CONTRACT_AMOUNT, ORIG_CONTRACT_AMOUNT_CNY, BORROWER_TYPE, BORROWER_ID, INDUSTRY_INFO, BORROWER_NATIONALITY, BORROWER_PROVINCE, BORROWER_CITY, BORROWER_COUNTY, LOAN_TRANSFEROR_ID, LOAN_TRANSFEROR_NAME, LOAN_CONTRACT_ORG_ID, LOAN_CONTRACT_ORG_NAME, LOAN_CONTRACT_ORG_PROVINCE, LOAN_CONTRACT_ORG_CITY, LOAN_CONTRACT_ORG_COUNTY, ENTERPRISE_INVESTOR_TYPE_FIRST, ENTERPRISE_INVESTOR_TYPE_SEC, ENTERPRISE_INVESTOR_TYPE_THIRD, ENTERPRISE_SCALE, LOAN_BASIS_ID, LOAN_PRD_TYPE, LOAN_ACTUAL_INVEST, LOAN_VDATE, LOAN_MDATE, LOAN_EXTENSION_DUE_DATE, RATE_FIXED, RATE_LEVEL, LOAN_GUARANTEE_MODE, LOAN_QUALITY, LOAN_STATE, LOAN_TRANSFEROR_RATE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, STATUS, DATA_SOURCE) VALUES( TEMP.ASSET_UUID, TEMP.ASSET_CODE, TEMP.ASSETS_INVEST, TEMP.EACH_PROPORTION, TEMP.LOANS_TYPE, TEMP.ORIG_CCY, TEMP.ORIG_CONTRACT_AMOUNT, TEMP.ORIG_CONTRACT_AMOUNT_CNY, TEMP.BORROWER_TYPE, TEMP.BORROWER_ID, TEMP.INDUSTRY_INFO, TEMP.BORROWER_NATIONALITY, TEMP.BORROWER_PROVINCE, TEMP.BORROWER_CITY, TEMP.BORROWER_COUNTY, TEMP.LOAN_TRANSFEROR_ID, TEMP.LOAN_TRANSFEROR_NAME, TEMP.LOAN_CONTRACT_ORG_ID, TEMP.LOAN_CONTRACT_ORG_NAME, TEMP.LOAN_CONTRACT_ORG_PROVINCE, TEMP.LOAN_CONTRACT_ORG_CITY, TEMP.LOAN_CONTRACT_ORG_COUNTY, TEMP.ENTERPRISE_INVESTOR_TYPE_FIRST, TEMP.ENTERPRISE_INVESTOR_TYPE_SEC, TEMP.ENTERPRISE_INVESTOR_TYPE_THIRD, TEMP.ENTERPRISE_SCALE, TEMP.LOAN_BASIS_ID, TEMP.LOAN_PRD_TYPE, TEMP.LOAN_ACTUAL_INVEST, TEMP.LOAN_VDATE, TEMP.LOAN_MDATE, TEMP.LOAN_EXTENSION_DUE_DATE, TEMP.RATE_FIXED, TEMP.RATE_LEVEL, TEMP.LOAN_GUARANTEE_MODE, TEMP.LOAN_QUALITY, TEMP.LOAN_STATE, TEMP.LOAN_TRANSFEROR_RATE, TEMP.CREATE_USER, TEMP.CREATE_TIME, TEMP.UPDATE_USER, TEMP.UPDATE_TIME, TEMP.CREATE_DEPT, TEMP.ORG_CODE, TEMP.DEPT_CODE, TEMP.STATUS, TEMP.DATA_SOURCE )

mapper.select:
SELECT PBC_ASSET_TYPE1,PBC_ASSET_TYPE2
FROM CHB_ASSET_INFO
WHERE ASSET_CODE = #{assetCode}
